int partition(std::vector<int>& v, int lo, int hi) {
    int pivot = v[hi];
    int i = lo - 1;
    for (int j = lo; j < hi; j++) {
        if (v[j] < pivot) { i++; std::swap(v[i], v[j]); }
    }
    std::swap(v[i+1], v[hi]);
